const motionKey='sv-alpha-gradient-paused';let paused=false;try{paused=localStorage.getItem(motionKey)==='true'}catch{}function updateMotion(){document.documentElement.classList.toggle('motion-paused',paused);document.querySelectorAll('.motion-switch').forEach(b=>{b.textContent=paused?'Включить градиент':'Остановить градиент';b.setAttribute('aria-pressed',String(paused));});}updateMotion();document.querySelectorAll('.motion-switch').forEach(b=>b.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem(motionKey,String(paused))}catch{}updateMotion()}));
